import{_ as i,o as c,c as d,j as o,a as t,G as a,aa as r,B as n}from"./chunks/framework.VLjJFeoF.js";const _=JSON.parse('{"title":"计算机网络","description":"","frontmatter":{},"headers":[],"relativePath":"docs/interview/net/index.md","filePath":"docs/interview/net/index.md","lastUpdated":1769531044000}'),s={name:"docs/interview/net/index.md"};function p(u,e,h,T,P,S){const l=n("ArticleMetadata");return c(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1769531044000"},[e[0]||(e[0]=o("h1",{id:"计算机网络",tabindex:"-1"},[t("计算机网络 "),o("a",{class:"header-anchor",href:"#计算机网络","aria-label":'Permalink to "计算机网络"'},"​")],-1)),a(l,{article:{}}),e[1]||(e[1]=r('<h2 id="_1-tcp-和-udp-区别" tabindex="-1">1.TCP 和 UDP 区别 <a class="header-anchor" href="#_1-tcp-和-udp-区别" aria-label="Permalink to &quot;1.TCP 和 UDP 区别&quot;">​</a></h2><ul><li><code>TCP</code> 面向连接，<code>UDP</code> 不需要建立连接</li><li><code>TCP</code> 是面向字节流的(可分割)，<code>UDP</code> 是面向报文的</li><li><code>TCP</code> 只能一对一通信，<code>UDP</code> 支持一对一，一对多，多对一，多对多</li><li><code>TCP</code> 可靠传输，使用流量控制和拥塞控制，<code>UDP</code> 不可靠</li><li><code>TCP</code> 头部开销大（20-60 字节），<code>UDP</code> 头部开销小（8 字节）</li></ul><h2 id="_2-http-状态码" tabindex="-1">2.HTTP 状态码 <a class="header-anchor" href="#_2-http-状态码" aria-label="Permalink to &quot;2.HTTP 状态码&quot;">​</a></h2><ul><li>1××：中间状态 <ul><li><code>101</code> Switching Protocols</li></ul></li><li>2××：成功 <ul><li><code>200</code> OK</li><li><code>204</code> No Content：不返回 body,埋点上报</li><li><code>206</code> Partial Content</li></ul></li><li>3xx：重定向 <ul><li><code>301</code> 永久重定向</li><li><code>302</code> 临时重定向 ；效果和 301 一样，只是语义不一样</li><li><code>304</code> 缓存重定向 协商缓存验证</li></ul></li><li>4xx：客户端错误 <ul><li><code>400</code> Bad Request：通用的错误码</li><li><code>401</code> unauthorized 未授权</li><li><code>403</code> Forbidden</li><li><code>404</code> Not Found</li><li><code>405</code> Method Not Allowed</li></ul></li><li>5xx：服务器错误 <ul><li><code>500</code> Internal Server Error：通用的错误码</li><li><code>502</code> Bad Gateway：网关/代理错误</li><li><code>503</code> Service Unavailable 服务不可用</li></ul></li></ul><h2 id="_3-http2-的特性" tabindex="-1">3.HTTP2 的特性 <a class="header-anchor" href="#_3-http2-的特性" aria-label="Permalink to &quot;3.HTTP2 的特性&quot;">​</a></h2><ul><li>二进制帧</li><li>多路复用</li><li>头部压缩</li><li>服务器推送</li></ul><p><strong>多路复用</strong>：</p><ul><li><code>HTTP/1.1</code>：同⼀时间⼀个 TCP 连接只能处理⼀个请求, 采⽤⼀问⼀答的形式, 上⼀个请求响应后才能处理下⼀个请求。由于浏览器最⼤ TCP 连接数的限制, 所以有了最⼤并发请求数的限制.</li><li><code>HTTP/2.0</code>：同域名下所有通信都在单个连接上完成，消除了因多个 TCP 连接⽽带来的延时和内存消耗。单个连接上可以并⾏交错的请求和响应，之间互不干扰。</li></ul><p>为什么 <code>HTTP/1.1</code> 不能实现多路复⽤?</p><ul><li><code>HTTP/2</code> 是基于⼆进制“帧”的协议，<code>HTTP/1.1</code> 是基于(报文)“⽂本分割”解析的协议。</li><li><code>HTTP1.1</code> 的报⽂结构中, 服务器需要不断的读⼊字节，直到遇到换⾏符, 或者说⼀个空⽩⾏. 处理顺序是串⾏的, ⼀个请求和⼀个响应需要通过⼀问⼀答的形式才能对应起来。</li><li><code>HTTP2.0</code> 中，有两个⾮常重要的概念，分别是<code>帧(frame)</code>和<code>流(stream）</code>。帧代表着最小的数据单位，每个帧会标识出该帧属于哪个流，流也就是多个帧组成的数据流。</li><li><code>多路复⽤</code>，就是在⼀个 <code>TCP</code> 连接中可以存在多条流。换句话说，也就是可以发送多个请求，对端可以通过帧中的标识知道属于哪个请求。通过这个技术，可以避免 HTTP 旧版本中的队头阻塞问题，极⼤的提⾼传输性能。</li></ul><h2 id="_4-https-的原理" tabindex="-1">4.HTTPS 的原理 <a class="header-anchor" href="#_4-https-的原理" aria-label="Permalink to &quot;4.HTTPS 的原理&quot;">​</a></h2><p>HTTPS 其实就是 HTTP+TLS 的传输方式，TLS 叫传输层安全，之前叫 SSL（安全套接层）。</p><p>因为 HTTP 属于明文传输，可以被截取到。那么就需要对传输报文进行加密，加密方式有两种：非对称和对称。对称就是同一个密钥进行加密解密，非对称就是有一组公私密钥，可以互相加解密。</p><p>那么 TLS 是怎么做的呢？</p><p>因为非对称加密的效率不高，对 HTTP 报文一般采用对称加密，然后通过非对称加密传输这个会话密钥。</p><p>比如客户端生成一个<code>会话密钥</code>通过一个<code>公钥</code>加密，服务端通过<code>私钥</code>解密获得会话密钥，就可以安全地传输报文了。</p><p>但是这个公钥不能安全地传输到客户端手里，即使加密也需要对应的密钥进行传输，现在的通过 <code>CA机构</code> 解决这个密钥的信任问题。</p><ol><li>服务端向 <code>CA机构</code>申请一个证书，这个证书，就是用 <code>CA机构的私钥</code> 加密过的 <code>网站的公钥</code>。</li><li>然后客户端请求得到这个证书，通过预装在客户端的 <code>CA机构的公钥</code> 进行解密和验证签名，得到这个<code>网站的公钥</code>。</li><li>简单的讲，客户端就可以生成一个<code>会话密钥</code>通过<code>网站的公钥</code>加密传输给服务端，服务端通过<code>网站的私钥</code>解密后就得到了这个<code>会话密钥</code>。</li></ol><p>但是，真实情况不是这个简单流程(RSA)，有密钥交换算法，比如 ECDHE，在请求返回证书的过程，服务端和客户端会分别交互两个随机数，然后自个通过协商好的算法参数生成第三个随机数，再通过这个三个随机数生成会话密钥，这个密钥是不需要传输的，两边都知道，之后就可以加密传输了。</p><h2 id="_5-从输入-url-到显示页面" tabindex="-1">5.从输入 URL 到显示页面 <a class="header-anchor" href="#_5-从输入-url-到显示页面" aria-label="Permalink to &quot;5.从输入 URL 到显示页面&quot;">​</a></h2><ul><li>浏览器处理 URL <ul><li>浏览器进程</li></ul></li><li>网络进程 发起请求 <ul><li>检查缓存</li><li>DNS 查找</li><li>HTTP(S) / TCP 连接</li></ul></li><li>响应请求，渲染进程渲染页面</li><li><strong>关键渲染路径</strong></li></ul><h2 id="_6-dns-解析" tabindex="-1">6.DNS 解析 <a class="header-anchor" href="#_6-dns-解析" aria-label="Permalink to &quot;6.DNS 解析&quot;">​</a></h2><p><strong>DNS（Domain Name System，域名系统）是一个将域名和 IP 地址相互映射的分布式服务</strong> 缓存：浏览器-操作系统-路由器-本地域名服务</p><ol><li>客户端发送请求给本地域名服务器，如果没有继续（递归）</li><li>本地域名服务器，向<strong>根域名服务器</strong>，返回<strong>顶级域名服务器</strong>地址，然后请求拿到<strong>权威域名服务器</strong>，最后请求拿到 IP 返回给客户端（迭代）</li></ol><p>一般我们向本地 DNS 服务器发送请求的方式就是<strong>递归查询</strong>，因为我们只需要发出一次请求，然后本地 DNS 服务器返回给我们最终的请求结果。而本地 DNS 服务器向其他域名服务器请求的过程是<strong>迭代查询</strong>的过程，因为每一次域名服务器只返回单次查询的结果，下一级的查询由本地 DNS 服务器自己进行。</p><h2 id="_7-长连接-长轮询-短轮询-websocket" tabindex="-1">7.长连接/长轮询/短轮询/websocket <a class="header-anchor" href="#_7-长连接-长轮询-短轮询-websocket" aria-label="Permalink to &quot;7.长连接/长轮询/短轮询/websocket&quot;">​</a></h2><ul><li><p>长连接：<code>Connection：keep-alive</code></p></li><li><p>长轮询：服务端将请求挂起一定的时间再返回（微信二维码）</p></li><li><p>短轮询：客户端每隔一段时间发送请求</p></li><li><p>websocket：全双工的协议，可以相互收发消息。</p></li><li><p>EventSource：server 到 client，支持文本</p></li></ul><h2 id="_8-csrf" tabindex="-1">8.CSRF <a class="header-anchor" href="#_8-csrf" aria-label="Permalink to &quot;8.CSRF&quot;">​</a></h2><p><strong>csrf：跨站请求伪造(Cross—Site Request Forgery)</strong> 攻击者利用 HTTP 请求会自动携带 cookie 的特定，利用用户的登陆状态发送恶意请求。 方法：自动发起 get/post 请求；诱导点击</p><p>CSRF 的过程：</p><ul><li>用户登录了 <code>a.com</code> ，有了 cookie</li><li>黑客引诱用户访问 <code>b.com</code> 网页，偷偷让用户访问了 <code>a.com/api/xxx</code>（干某件事）</li><li><code>a.com</code> api 接口收到请求 cookie ，误以为是真实用户的请求，就受理了</li></ul><p><strong>防御</strong>：</p><ul><li>CSRF token 验证</li><li>HTTP 请求头的 referer 字段（可以伪造），Origin(不含具体 url)</li><li>SameSite 限制 Cookie 在跨站请求时不会被发送 <ul><li>Strict，必须是相同站点</li><li>Lax 宽松，允许部分类型，比如 a 链接</li><li>None 不限制</li></ul></li></ul><h2 id="_9-xss" tabindex="-1">9.XSS <a class="header-anchor" href="#_9-xss" aria-label="Permalink to &quot;9.XSS&quot;">​</a></h2><p><strong>XSS：跨站脚本(Cross Site Scripting)</strong></p><ul><li><strong>存储型</strong>：将恶意代码存在服务器，请求含有恶意代码的页面。</li><li><strong>反射型</strong>：构建含有恶意代码的 url，服务器不存储，后端直接返回到页面。</li><li><strong>DOM 型</strong>：前端解析恶意代码执行，相比前两者，属于前端的漏洞。</li></ul><p><strong>防御</strong>：</p><ul><li>本质是防止恶意脚本的注入</li><li>存储型和反射性：改成纯前端渲染， 对输入内容进行转义和过滤</li><li>DOM 型：谨慎  innerHTML/ v-html ，字符串做代码执行的 eval,Function</li><li>CSP 内容安全策略 Content-Security-Policy，白名单告诉浏览器认可的资源来源，http 响应头/meta</li><li>很多 XSS 盗取是 cookie 的，可以设置 Cookie 的 HttpOnly</li></ul><h2 id="_10-前端鉴权方案有哪些" tabindex="-1">10.前端鉴权方案有哪些 <a class="header-anchor" href="#_10-前端鉴权方案有哪些" aria-label="Permalink to &quot;10.前端鉴权方案有哪些&quot;">​</a></h2><p>概念：鉴权（<code>Authentication</code>）：验证用户是否拥有访问系统的权利</p><p>常见的鉴权方式有以下几种方式：</p><ol><li><code>基本认证方案</code> 不安全，密码容易泄露</li><li><code>session-cookie</code> session 需要存储， 依赖 cookie ，不安全：CSRF</li><li><code>token</code> 前端存储 token，避免 CSRF，为了减少 token 被盗风险，缩短有效期，使用<code>Access Token</code>和<code>Refresh Token</code>(用于获取前者,时效长)</li><li><code>JWT</code> token 验证服务端需要查询用户信息鉴权，JWT 的 Payload 负载中存储常用信息，服务端不存储状态，一旦签发无法废除 JWT 由三部分组成： Header 头部、 Payload 负载 和 Signature 签名, 对这个 JSON 对象加密，</li><li><code>SSO</code><ul><li>同域：设置 Cookie 的 Domain 为 .baidu.com</li><li>不同域：SSO.com 返回 token 验证 token 跳转</li></ul></li><li><code>OAuth2.0</code> 略</li></ol><blockquote><ul><li><a href="https://juejin.cn/post/7129298214959710244#heading-26" target="_blank" rel="noreferrer">一文教你搞定所有前端鉴权与后端鉴权方案，让你不再迷惘</a></li><li><a href="https://juejin.cn/post/6898630134530752520" target="_blank" rel="noreferrer">前端鉴权的兄弟们：cookie、session、token、jwt、单点登录</a></li></ul></blockquote><h2 id="_11-http-头部有哪些" tabindex="-1">11.http 头部有哪些 <a class="header-anchor" href="#_11-http-头部有哪些" aria-label="Permalink to &quot;11.http 头部有哪些&quot;">​</a></h2><ul><li><p>基础</p><ul><li><code>Accept</code> | <code>Content-Type</code> 内容类型</li><li><code>Accept-Encoding</code> | <code>Content-Encoding</code> 编码方式</li><li><code>Connection:Keep-Alive</code> 长连接</li><li><code>Host</code> 主机名</li><li><code>User-Agent</code> 浏览器信息</li><li><code>Referer</code> 来源页面</li></ul></li><li><p>Cookie：<code>Cookie</code> | <code>Set-Cookie</code></p></li><li><p>缓存</p></li><li><p>CORS</p></li></ul><h2 id="_12-cookie-有哪些字段" tabindex="-1">12.cookie 有哪些字段 <a class="header-anchor" href="#_12-cookie-有哪些字段" aria-label="Permalink to &quot;12.cookie 有哪些字段&quot;">​</a></h2>',46))])}const g=i(s,[["render",p]]);export{_ as __pageData,g as default};
